using System;
using System.Security.Cryptography;

namespace Nethermind.Pqz;

/// <summary>Review R4-C4: a start-up known-answer set for ML-DSA-44 / -65 / -87 through <see cref="MlDsa.Verify(MLDsaAlgorithm, int, int, ReadOnlySpan{byte})"/>
/// (the precompiles' EIP-8355 path, whatever libcrypto .NET loads). Per level, from one valid input <c>pk ‖ sig ‖ msg</c>
/// (ML-DSA-44: EIP-8355's test vector "wycheproof mldsa_44_verify_test tcId 1", pq_external.json; ML-DSA-65: the
/// mldsa65 UA proof of possession of pq_signatures.json; ML-DSA-87, CTR-UA-39: the mldsa87 one; all verified by MlDsaTests): the valid input, a bit flip in
/// c̃, two hint indices of one polynomial out of order, a non-zero hint padding byte, a hint count over ω, z's first
/// coefficient at γ1 (out of range), t1 at its maximum (every t1 byte 0xff), a bit flip in the message. The verdict bytes
/// (1, then seven 0) of the three levels hash (SHA-256) to <see cref="ExpectedHash"/>; <see cref="PqzStartupCheck"/> refuses
/// with PQZ-REFUSE on any other hash.</summary>
public static class MlDsaKat
{
    public const string ExpectedHash = "605390e5a369ee568b19ead1733af824c7c1d286d7d24b86283238fc44a99334";

    /// <summary>(algorithm, |pk|, |sig|, |c̃|, k, ω) of FIPS 204's ML-DSA-44 / -65 / -87.</summary>
    private static readonly (MLDsaAlgorithm alg, int pk, int sig, int ct, int k, int omega, int zBits, string input)[] Levels =
    [
        (MLDsaAlgorithm.MLDsa44, MlDsa.Pk44, MlDsa.Sig44, 32, 4, 80, 18, In44),
        (MLDsaAlgorithm.MLDsa65, MlDsa.Pk65, MlDsa.Sig65, 48, 6, 55, 20, In65),
        (MLDsaAlgorithm.MLDsa87, MlDsa.Pk87, MlDsa.Sig87, 64, 8, 75, 20, In87),
    ];

    /// <summary>The cases' inputs of one level, in verdict order.</summary>
    public static byte[][] Cases(int level)
    {
        var (_, pk, sig, ct, k, omega, zBits, hex) = Levels[level];
        byte[] good = Convert.FromHexString(hex);
        int h = pk + sig - omega - k; // the hint encoding y: ω index bytes, then k cumulative counts
        byte[] Edit(Action<byte[]> f) { byte[] x = (byte[])good.Clone(); f(x); return x; }
        return
        [
            good,
            Edit(x => x[pk] ^= 1),
            Edit(x =>
            {
                // the first polynomial with two hints: swap its first two (strictly increasing) indices
                int start = 0, i = 0;
                while (x[h + omega + i] - start < 2) start = x[h + omega + i++];
                (x[h + start], x[h + start + 1]) = (x[h + start + 1], x[h + start]);
            }),
            Edit(x =>
            {
                if (x[h + omega + k - 1] >= omega) throw new InvalidOperationException("ML-DSA KAT: no hint padding");
                x[h + omega - 1] = 1;
            }),
            Edit(x => x[h + omega + k - 1] = (byte)(omega + 1)),
            Edit(x =>
            {
                // z's first coefficient packed as γ1 − z = 0 (zBits little-endian bits): z = γ1, ≥ γ1 − β
                x[pk + ct] = 0;
                x[pk + ct + 1] = 0;
                x[pk + ct + 2] &= (byte)~((1 << (zBits - 16)) - 1);
            }),
            Edit(x => x.AsSpan(32, pk - 32).Fill(0xff)),
            Edit(x => x[^1] ^= 1),
        ];
    }

    /// <summary>The OpenSSL version .NET loaded (<c>OPENSSL_VERSION_NUMBER</c>, hex), for <c>PQZ-START</c>.</summary>
    public static string OpenSslVersion => OperatingSystem.IsWindows() ? "none" : $"0x{SafeEvpPKeyHandle.OpenSslVersion:x}";

    /// <summary>The verdicts' SHA-256 (lower-case hex).</summary>
    public static string Run()
    {
        byte[] v = new byte[8 * Levels.Length];
        for (int l = 0; l < Levels.Length; l++)
        {
            byte[][] c = Cases(l);
            for (int i = 0; i < c.Length; i++) v[8 * l + i] = MlDsa.Verify(Levels[l].alg, Levels[l].pk, Levels[l].sig, c[i])[31];
        }
        return Convert.ToHexStringLower(SHA256.HashData(v));
    }

    private const string In44 = "";
    private const string In65 = "";
    private const string In87 = "";
}
